/**
 * Predict motor fault condition and compute real-time metrics.
 * 
 * @param features      Array of PDM_FEATURE_COUNT input features
 * @param confidence    Output pointer for model confidence (0.0 to 1.0)
 * @param health_index  Output pointer for continuous Health Index (0.0 to 100.0)
 * @return              Predicted class index (0 to PDM_CLASS_COUNT - 1)
 */
inline int pdmPredict(
    const float features[PDM_FEATURE_COUNT],
    float *confidence = nullptr,
    float *health_index = nullptr
) {
  float votes[PDM_CLASS_COUNT] = {0.0f};

  pdmTree0(features, votes);
  pdmTree1(features, votes);
  pdmTree2(features, votes);
  pdmTree3(features, votes);
  pdmTree4(features, votes);
  pdmTree5(features, votes);
  pdmTree6(features, votes);
  pdmTree7(features, votes);
  pdmTree8(features, votes);
  pdmTree9(features, votes);
  pdmTree10(features, votes);
  pdmTree11(features, votes);
  pdmTree12(features, votes);
  pdmTree13(features, votes);
  pdmTree14(features, votes);
  pdmTree15(features, votes);
  pdmTree16(features, votes);
  pdmTree17(features, votes);
  pdmTree18(features, votes);
  pdmTree19(features, votes);
  pdmTree20(features, votes);
  pdmTree21(features, votes);
  pdmTree22(features, votes);
  pdmTree23(features, votes);
  pdmTree24(features, votes);
  pdmTree25(features, votes);
  pdmTree26(features, votes);
  pdmTree27(features, votes);
  pdmTree28(features, votes);
  pdmTree29(features, votes);
  pdmTree30(features, votes);
  pdmTree31(features, votes);
  pdmTree32(features, votes);
  pdmTree33(features, votes);
  pdmTree34(features, votes);

  // Find argmax class
  int best_class = 0;
  float max_vote = votes[0];
  for (int i = 1; i < PDM_CLASS_COUNT; ++i) {
    if (votes[i] > max_vote) {
      max_vote = votes[i];
      best_class = i;
    }
  }

  if (confidence != nullptr) {
    *confidence = max_vote / (float)PDM_NUM_TREES;
  }

  if (health_index != nullptr) {
    *health_index = (votes[PDM_HEALTHY_CLASS_INDEX] / (float)PDM_NUM_TREES) * 100.0f;
  }

  return best_class;
}

